#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>
WiFiClient network;
PubSubClient mqtt(network);
DHT sensor(23, DHT22);
void setup() {
  Serial.begin(115200);
  sensor.begin();
  WiFi.begin("VoltNet", "pass");
  while (WiFi.status() != WL_CONNECTED) delay(50);
  mqtt.setServer("broker.voltquest.local", 1883);
  mqtt.connect("weather-station");
}
void loop() {
  mqtt.loop();
  float temperature = sensor.readTemperature();
  String payload = String(temperature);
  mqtt.publish("weather/temperature", payload.c_str());
  Serial.println(payload);
  delay(500);
}
